    "type": "hotspot",
    "useConfigHotspot": true,
    "prompt": "Select the line that shows a classic symptom of a duplex mismatch.",
    "scenario": "<div class=\"scenario-text\"><p>An engineer is reviewing interface statistics on a port connected to an older server.</p></div>",
    "nodes": [
      { "id": "l1", "label": "0 input errors, 0 CRC, 0 frame" },
      { "id": "l2", "label": "1523 collisions, 487 late collisions" },
      { "id": "l3", "label": "0 output errors, 0 interface resets" },
      { "id": "l4", "label": "Full-duplex, 1000Mb/s" },
      { "id": "l5", "label": "Last clearing of 'show interface' counters never" }
    ],
    "correct": ["l2"],
